std::vector<Node> path;
std::priority_queue<std::pair<int, Node>, std::vector<std::pair<int, Node>>, std::greater<std::pair<int, Node>>> queue;
std::unordered_set<int> visited;
std::unordered_map<int, int> distance;
std::unordered_map<int, int> previous;

queue.push({0, graph.nodes[start_idx]});
distance[start_idx] = 0;

while (!queue.empty()) {
    Node current_node = queue.top().second;
    queue.pop();
    int current_idx = current_node.index;

    if (current_idx == end_idx) {
        while (current_idx != start_idx) {
            path.push_back(current_node);
            current_idx = previous[current_idx];
            current_node = graph.nodes[current_idx];
        }
        path.push_back(graph.nodes[start_idx]);
        std::reverse(path.begin(), path.end());
        return path;
    }

    visited.insert(current_idx);

    for (const auto& neighbor : graph.neighbors[current_idx]) {
        int neighbor_idx = neighbor.index;
        if (visited.find(neighbor_idx) == visited.end()) {
            int tentative_distance = distance[current_idx] + graph.get_edge_weight(current_idx, neighbor_idx);
            if (distance.find(neighbor_idx) == distance.end() || tentative_distance < distance[neighbor_idx]) {
                distance[neighbor_idx] = tentative_distance;
                previous[neighbor_idx] = current_idx;
                int heuristic = graph.get_heuristic(neighbor_idx, end_idx);
                queue.push({tentative_distance + heuristic, neighbor});
            }
        }
    }
}

return path;

